			 , RSC_PRVSV_ID                      /* 자원제공서비스ID */
			 , RSC_PVSN_MBD_ID                   /* 자원제공주체ID */
			 , HBEM_SRV_ID                       /* 행복e음서비스ID */
			 , WLRSC_PRVSV_CLS_ID                /* 복지자원제공서비스분류ID */
			 , UP_PVSN_SRV_ID                    /* 상위제공서비스ID */
			 , RSC_PRVSV_NM                      /* 자원제공서비스명 */
			 , RSC_PRVSV_PGM_NM                  /* 자원제공서비스프로그램명 */
			 , RSC_PRVSV_DC                      /* 자원제공서비스설명 */
			 , RSC_PRVSV_BGNG_YMD                /* 자원제공서비스시작일자 */
		 	 , RSC_PRVSV_END_YMD                 /* 자원제공서비스종료일자 */
			 , RSC_PVSN_SRV_TCD                  /* 자원제공서비스유형코드 */
			 , RSC_PRVSV_OTM_YN                  /* 자원제공서비스일회성여부 */
			 , RSC_PRVSV_SCD                     /* 자원제공서비스상태코드 */
			 , RSC_PRVSV_CHR_USRID               /* 자원제공서비스담당사용자ID */
			 , PIC_FLNM                          /* 담당자성명 */
