			 , PIC_MPNO                          /* 담당자휴대전화번호 */
			 , PIC_EMADR                         /* 담당자이메일주소 */
			 , HMPG_URL                          /* 홈페이지URL */
			 , USFL_QTY_MNG_YN                   /* 가용수량관리여부 */
			 , PVSN_QTY                          /* 제공수량 */
			 , PVSN_AMT                          /* 제공금액 */
			 , DPSTN_TAM                         /* 기탁총액 */
			 , DPSTN_TTL_QTY                     /* 기탁총수량 */
			 , DPSTN_PVSN_CYC_CD                 /* 기탁제공주기코드 */
			 , RSC_PVSN_SRSP_UNIT_CD             /* 자원제공서비스지원단위코드 */
			 , DPPS_FLNM                         /* 기탁자성명 */
			 , DPPS_TELNO                        /* 기탁자전화번호 */
			 , DPSTN_UNIT_UPRC                   /* 기탁단위단가 */
			 , SLBNAM_AMT                        /* 본인부담금금액 */
			 , SPRT_TMCNT                        /* 지원횟수 */
			 , RSC_PVSN_CYC_CD                   /* 자원제공주기코드 */
			 , UTL_FXCNT                         /* 이용정원수 */
