			 , UTL_WTPS_NT                       /* 이용대기자수 */
			 , SRVC_NOPE                         /* 봉사인원수 */
			 , SRVC_PSBLT_REGN_CN                /* 봉사가능지역내용 */
			 , DPPS_ZIP                          /* 기탁자우편번호 */
			 , DPPS_ADDR                         /* 기탁자주소 */
			 , RPRSV_FLNM                        /* 대표자성명 */
			 , DPSTN_CN                          /* 기탁내용 */
			 , DPSTN_AMT_DPST_YMD                /* 기탁금액입금일자 */
			 , RSC_PVSN_DPSTN_TCD                /* 자원제공기탁유형코드 */
			 , DPPS_NO                           /* 기탁자번호 */
			 , PLNG_BIZ_YN                       /* 기획사업여부 */
			 , DSGN_DPSTN_DCD                    /* 지정기탁구분코드 */
			 , WLRSC_PRVSV_ACC_ID                /* 복지자원제공서비스계좌ID */
			 , RSC_PRVSV_TRSM_YN                 /* 자원제공서비스전송여부 */
			 , DPST_CFDOC_TRSM_YN                /* 입금확인서전송여부 */
			 , RSC_PRVSV_LINK_DMND_YMD           /* 자원제공서비스연계요청일자 */
			 , RSC_PRVSV_ADRGN_CD                /* 자원제공서비스행정지역코드 */
			 , MM_PERD_DPSTN_DPST_DAY            /* 월정기기탁입금일 */
			 , CMCH_ITEM_DTL_CCD                 /* 공동모금회품목상세분류코드 */
			 , APLY_USRID                        /* 신청사용자ID */
			 , APLY_DT                           /* 신청일시 */
			 , APRV_USRID                        /* 승인사용자ID */
			 , APRV_DT                           /* 승인일시 */
			 , RSC_APRV_SCD                      /* 자원승인상태코드 */
			 , RSC_RJCT_RSN_CN                   /* 자원반려사유내용 */
			 , DEL_YN                            /* 삭제여부 */
			 , RSC_DEL_RSN_CD                    /* 자원삭제사유코드 */
			 , DEL_RSN_ETC_CN                    /* 삭제사유기타내용 */
			 , RSC_PRVSV_SHAR_RNG_CD             /* 자원제공서비스공유범위코드 */
			 , SRV_RQST_RNG_DCD                  /* 서비스의뢰범위구분코드 */
			 , REGN_CARE_RSC_YN                  /* 지역돌봄자원여부 */
			 , RSC_PRVSV_CHG_RSN_CN              /* 자원제공서비스변경사유내용 */
			 , SINFO_INCL_RSC_YN                 /* 민감정보포함자원여부 */
			 , ONAP_PSBLT_YN                     /* 온라인신청가능여부 */
			 , ATCFL_ID                          /* 첨부파일ID */
			 , INST_SYS_CD                       /* 기관시스템코드 */
			 , REG_INFO_SHAR_INST_ID             /* 등록정보공유기관ID */
			 , RSC_PRVSV_TRGT_CRTR_DTL_CN        /* 자원제공서비스대상기준상세내용 */
			 , RSC_PRVSV_SHAR_RNG_DTL_CN         /* 자원제공서비스공유범위상세내용 */
			 , RSC_TAG_CNCT_DTL_CN               /* 자원태그연결상세내용 */
			 , RSC_PRVSV_HIST_SHAR_RNG_DTL_CN    /* 자원제공서비스이력공유범위상세내용 */
			 , RSC_PRVSV_ETC_DTL_CN              /* 자원제공서비스기타상세내용 */
			 , ESB_TX_ID                         /* 연계트랜젝션아이디 */
			 , ESB_SEQ                           /* 연계시퀸스 */
			 , ESB_IF_ID                         /* 연계인터페이스ID */
			 , SND_CD                            /* 송신기관코드 */
			 , RCV_CD                            /* 수신기관코드 */
			 , ESB_FILE_NAME                     /* 연계파일이름 */
			 , CREATE_TIME                       /* 데이터생성일시 */
			 , ESB_INIT_TIME                     /* 연계시작일시 */
			 , ESB_COMPLITE_TIME                 /* 연계종료일시 */
			 , ESB_STATUS                        /* 연계상태 */
             )
        VALUES
             ( #{RSC_PVSN_SYS_DCD}
			 , #{SRC_INST_RSC_PVSN_MBD_ID}
			 , #{SRC_INST_RSC_PRVSV_ID}
			 , #{RSC_PRVSV_ID}
			 , #{RSC_PVSN_MBD_ID}
			 , #{HBEM_SRV_ID}
			 , #{WLRSC_PRVSV_CLS_ID}
			 , #{UP_PVSN_SRV_ID}
			 , #{RSC_PRVSV_NM}
			 , #{RSC_PRVSV_PGM_NM}
			 , #{RSC_PRVSV_DC}
			 , #{RSC_PRVSV_BGNG_YMD}
			 , #{RSC_PRVSV_END_YMD}
			 , #{RSC_PVSN_SRV_TCD}
			 , #{RSC_PRVSV_OTM_YN}
			 , #{RSC_PRVSV_SCD}
			 , #{RSC_PRVSV_CHR_USRID}
			 , #{PIC_FLNM}
			 , #{PIC_TELNO}
			 , #{PIC_MPNO}
			 , #{PIC_EMADR}
			 , #{HMPG_URL}
			 , #{USFL_QTY_MNG_YN}
			 , #{PVSN_QTY}
			 , #{PVSN_AMT}
			 , #{DPSTN_TAM}
			 , #{DPSTN_TTL_QTY}
			 , #{DPSTN_PVSN_CYC_CD}
			 , #{RSC_PVSN_SRSP_UNIT_CD}
			 , #{DPPS_FLNM}
			 , #{DPPS_TELNO}
			 , #{DPSTN_UNIT_UPRC}
			 , #{SLBNAM_AMT}
			 , #{SPRT_TMCNT}
			 , #{RSC_PVSN_CYC_CD}
			 , #{UTL_FXCNT}
			 , #{UTL_NOPE}
			 , #{UTL_PSBLT_NOPE}
			 , #{UTL_WTPS_NT}
			 , #{SRVC_NOPE}
			 , #{SRVC_PSBLT_REGN_CN}
			 , #{DPPS_ZIP}
			 , #{DPPS_ADDR}
			 , #{RPRSV_FLNM}
			 , #{DPSTN_CN}
			 , #{DPSTN_AMT_DPST_YMD}
			 , #{RSC_PVSN_DPSTN_TCD}
			 , #{DPPS_NO}
			 , #{PLNG_BIZ_YN}
			 , #{DSGN_DPSTN_DCD}
			 , #{WLRSC_PRVSV_ACC_ID}
			 , #{RSC_PRVSV_TRSM_YN}
			 , #{DPST_CFDOC_TRSM_YN}
			 , #{RSC_PRVSV_LINK_DMND_YMD}
			 , #{RSC_PRVSV_ADRGN_CD}
			 , #{MM_PERD_DPSTN_DPST_DAY}
			 , #{CMCH_ITEM_DTL_CCD}
			 , #{APLY_USRID}
			 , #{APLY_DT}
			 , #{APRV_USRID}
			 , #{APRV_DT}
			 , #{RSC_APRV_SCD}
			 , #{RSC_RJCT_RSN_CN}
			 , #{DEL_YN}
			 , #{RSC_DEL_RSN_CD}
			 , #{DEL_RSN_ETC_CN}
			 , #{RSC_PRVSV_SHAR_RNG_CD}
			 , #{SRV_RQST_RNG_DCD}
			 , #{REGN_CARE_RSC_YN}
			 , #{RSC_PRVSV_CHG_RSN_CN}
			 , #{SINFO_INCL_RSC_YN}
			 , #{ONAP_PSBLT_YN}
			 , #{ATCFL_ID}
			 , #{INST_SYS_CD}
			 , #{REG_INFO_SHAR_INST_ID}
			 , #{RSC_PRVSV_TRGT_CRTR_DTL_CN}
			 , #{RSC_PRVSV_SHAR_RNG_DTL_CN}
			 , #{RSC_TAG_CNCT_DTL_CN}
			 , #{RSC_PRVSV_HIST_SHAR_RNG_DTL_CN}
			 , #{RSC_PRVSV_ETC_DTL_CN}
			 , ''
			 , ( SELECT /*+ INDEX_DESC(T1 INDEX1) */
			            NVL(MAX(T1.ESB_SEQ),0) + 1                      
                   FROM CAB210 T1 )
             , 'INFIF_IR_SSI_FS_03'
		     , 'MOG'
		     , 'SSI'
		     , ''
		     , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISSFF3')
		     , ''
		     , ''
		     , 'N'
		     )

    INSERT /* isry.itgcm.linkmng.outsd.mapper.LinkMohwJobMapper.insertPvsnMby(공유자원 제공주체 사보정 송신 데이터 등록) */
      INTO CAB200 
	     ( RSC_PVSN_SYS_DCD             /* 자원제공시스템구분코드 */
	     , SRC_INST_RSC_PVSN_MBD_ID     /* 원천기관자원제공주체ID */
	     , RSC_PVSN_MBD_ID              /* 자원제공주체ID */
	     , RSC_PVSN_MBD_NM              /* 자원제공주체명 */
	     , RSC_PVSN_BRNC_NM             /* 자원제공지점명 */
	     , PVSN_BGNG_YMD                /* 제공시작일자 */
	     , PVSN_END_YMD                 /* 제공종료일자 */
	     , IDMB_ID                      /* 개인주체ID */
	     , SRV_INST_ID                  /* 서비스기관ID */
	     , RSC_PVSN_MBD_DC              /* 자원제공주체설명 */
	     , RSC_PVSN_MBD_SCD             /* 자원제공주체상태코드 */
	     , RSC_PVSN_MBD_DCD             /* 자원제공주체구분코드 */
	     , SRV_RQST_INST_TYP_DTL_CD     /* 서비스의뢰기관유형상세코드 */
	     , BZMN_DCD                     /* 사업자구분코드 */
	     , FACL_INST_DCD                /* 시설기관구분코드 */
	     , WLFCL_KCD                    /* 복지시설종류코드 */
	     , BRNO                         /* 사업자등록번호 */
	     , RGTR_OGDP_SGG_ADRGN_CD       /* 등록자소속시군구행정지역코드 */
	     , PVSN_MBD_LOCTN_SGG_ADRGN_CD  /* 제공주체소재지시군구행정지역코드 */
	     , PVSN_MBD_LOCTN_EMD_ADRGN_CD  /* 제공주체소재지읍면동행정지역코드 */
	     , LOCTN_ZIP                    /* 소재지우편번호 */
	     , PVSN_MBD_LOCTN_RDNM_CD       /* 제공주체소재지도로명코드 */
	     , LOCTN_RDNMADR                /* 소재지도로명주소 */
	     , LOCTN_RDNM_DTLADR            /* 소재지도로명상세주소 */
	     , PVSN_MBD_LOCTN_STDG_CD       /* 제공주체소재지법정동코드 */
	     , LOCTN_STDG_BASEADR           /* 소재지법정동기본주소 */
	     , LOCTN_STDG_DTLADR            /* 소재지법정동상세주소 */
	     , RSC_PVSN_MBD_CHR_USRID       /* 자원제공주체담당사용자ID */
	     , PIC_FLNM                     /* 담당자성명 */
	     , PIC_TELNO                    /* 담당자전화번호 */
	     , PIC_MPNO                     /* 담당자휴대전화번호 */
	     , PIC_EMADR                    /* 담당자이메일주소 */
	     , APLY_USRID                   /* 신청사용자ID */
	     , APLY_DT                      /* 신청일시 */
	     , APRV_USRID                   /* 승인사용자ID */
	     , APRV_DT                      /* 승인일시 */
	     , RSC_APRV_SCD                 /* 자원승인상태코드 */
	     , RSC_RJCT_RSN_CN              /* 자원반려사유내용 */
	     , DEL_YN                       /* 삭제여부 */
	     , RSC_DEL_RSN_CD               /* 자원삭제사유코드 */
	     , DEL_RSN_ETC_CN               /* 삭제사유기타내용 */
	     , RPRS_PVSN_MBD_YN             /* 대표제공주체여부 */
	     , INTG_CARE_CNTER_YN           /* 통합돌봄창구여부 */
	     , RSC_PVSN_MBD_CHG_RSN_CN      /* 자원제공주체변경사유내용 */
	     , ATCFL_ID                     /* 첨부파일ID */
	     , INST_SYS_CD                  /* 기관시스템코드 */
	     , REG_INFO_SHAR_INST_ID        /* 등록정보공유기관ID */
	     , RSC_PVSN_MBD_ADDR_MANT_YN    /* 자원제공주체주소정비여부 */
	     , RSC_PVSN_MBD_ADDR_LO         /* 자원제공주체주소경도 */
	     , RSC_PVSN_MBD_ADDR_LA         /* 자원제공주체주소위도 */
	     , RSC_PVSN_MBD_MOU_DTL_CN      /* 자원제공주체MOU상세내용 */
	     , RSC_PVSN_MBD_ETC_DTL_CN      /* 자원제공주체기타상세내용 */
	     , ESB_TX_ID                    /* 연계트랜젝션아이디 */
	     , ESB_SEQ                      /* 연계시퀸스 */
	     , ESB_IF_ID                    /* 연계인터페이스ID */
	     , SND_CD                       /* 송신기관코드 */
	     , RCV_CD                       /* 수신기관코드 */
	     , ESB_FILE_NAME                /* 연계파일이름 */
	     , CREATE_TIME                  /* 데이터생성일시 */
	     , ESB_INIT_TIME                /* 연계시작일시 */
	     , ESB_COMPLITE_TIME            /* 연계종료일시 */
	     , ESB_STATUS                   /* 연계상태 */ 
	     )
    VALUES
	     ( #{RSC_PVSN_SYS_DCD}
	     , #{SRC_INST_RSC_PVSN_MBD_ID}
	     , #{RSC_PVSN_MBD_ID}
	     , #{RSC_PVSN_MBD_NM}
	     , #{RSC_PVSN_BRNC_NM}
	     , #{PVSN_BGNG_YMD}
	     , #{PVSN_END_YMD}
	     , #{IDMB_ID}
	     , #{SRV_INST_ID}
	     , #{RSC_PVSN_MBD_DC}
	     , #{RSC_PVSN_MBD_SCD}
	     , #{RSC_PVSN_MBD_DCD}
	     , #{SRV_RQST_INST_TYP_DTL_CD}
	     , #{BZMN_DCD}
	     , #{FACL_INST_DCD}
	     , #{WLFCL_KCD}
	     , #{BRNO}                          
	     , #{RGTR_OGDP_SGG_ADRGN_CD}
	     , #{PVSN_MBD_LOCTN_SGG_ADRGN_CD}
	     , #{PVSN_MBD_LOCTN_EMD_ADRGN_CD}
	     , #{LOCTN_ZIP}
	     , #{PVSN_MBD_LOCTN_RDNM_CD}
	     , #{LOCTN_RDNMADR}
	     , #{LOCTN_RDNM_DTLADR}
	     , #{PVSN_MBD_LOCTN_STDG_CD}
	     , #{LOCTN_STDG_BASEADR}
	     , #{LOCTN_STDG_DTLADR}
	     , #{RSC_PVSN_MBD_CHR_USRID}
	     , #{PIC_FLNM}
	     , #{PIC_TELNO}
	     , #{PIC_MPNO}
	     , #{PIC_EMADR}
	     , #{APLY_USRID}
	     , #{APLY_DT}
	     , #{APRV_USRID}
	     , #{APRV_DT}
	     , #{RSC_APRV_SCD}
	     , #{RSC_RJCT_RSN_CN}
	     , #{DEL_YN}
	     , #{RSC_DEL_RSN_CD}
	     , #{DEL_RSN_ETC_CN}
	     , #{RPRS_PVSN_MBD_YN}
	     , #{INTG_CARE_CNTER_YN}
	     , #{RSC_PVSN_MBD_CHG_RSN_CN}
	     , #{ATCFL_ID}
	     , #{INST_SYS_CD}
	     , #{REG_INFO_SHAR_INST_ID}
	     , #{RSC_PVSN_MBD_ADDR_MANT_YN}
	     , #{RSC_PVSN_MBD_ADDR_LO}
	     , #{RSC_PVSN_MBD_ADDR_LA}
	     , #{RSC_PVSN_MBD_MOU_DTL_CN}
	     , #{RSC_PVSN_MBD_ETC_DTL_CN}
	     , ''
	     , ( SELECT /*+ INDEX_DESC(T1 INDEX1) */
	                NVL(MAX(T1.ESB_SEQ),0) + 1                      
	           FROM CAB200 T1 )
	     , 'INFIF_IR_SSI_FS_04'
	     , 'MOG'
	     , 'SSI'
	     , ''
	     , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISSFF3')
	     , ''
	     , ''
	     , 'N'
         )

INSERT /* isry.itgcm.linkmng.outsd.mapper.LinkMohwJobMapper.insertCaseMng(사례관리 사보정 송신 데이터 등록) */
  INTO CAB400 /* 사례관리 송신 */
     ( ESB_SEQ            /* 연계시퀸스 */
     , TRPR_RRNO          /* 대상자주민등록번호 */
     , TRPR_RRNO_ENCPT    /* 대상자주민등록번호암호화 */
     , CSMG_NO            /* 사례관리 번호 */
     , ESB_TX_ID          /* 연계트랜젝션아이디 */
     , ESB_IF_ID          /* 연계인터페이스아이디 */
     , SND_CD             /* 송신기관번호 */
     , RCV_CD             /* 수신기관번호 */
     , CREATE_TIME        /* 데이터생성일시 */
     , ESB_FILE_NAME      /* 연계파일이름 */
     , ESB_INIT_TIME      /* 연계시작일시 */
     , ESB_COMPLITE_TIME  /* 연계종료일시 */
     , ESB_STATUS         /* 연계상태 */
     /*20230310 추가*/
     , CSMG_DGR    /*사례관리차수*/
     , CSMG_TYP_ID /*사례관리유형ID*/
     , CSMG_TRGT_DCD   /*사례관리대상구분코드*/
     , CSMG_STD_TSKPRC_ID  /*사례관리표준업무처리ID*/
     , CSMG_EXTIF_INST_ID  /*사례관리외부연계기관ID*/
     , CHR_USRID   /*담당사용자ID*/
     , CTADR   /*연락처*/
     , CSMG_PIC_FLNM   /*사례관리담당자성명*/
     , CSMG_BGNG_YMD   /*사례관리시작일자*/
     , CSMG_END_YMD    /*사례관리종료일자*/
     , CSMG_DTL_DCD    /*사례관리상세구분코드*/
     , FRST_REG_PTM    /*최초등록시점*/
     , LAST_MDFCN_PTM  /*최종수정시점*/
     )
VALUES
     (CAB400_SQ01.NEXTVAL
     , #{TRPR_RRNO}
     , #{TRPR_RRNO_ENCPT}
     , #{CSMG_NO}
     , ''
     , 'INFIF_IR_SSI_FS_05'
     , 'MOG'
     , 'SSI'
     , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISSFF3')
     , ''
     , ''
     , ''
     , 'N'
     /*20230310 추가*/
     , #{CSMG_DGR}
     , #{CSMG_TYP_ID}
     , #{CSMG_TRGT_DCD}
     , #{CSMG_STD_TSKPRC_ID}
     , #{CSMG_EXTIF_INST_ID}
     , #{CHR_USRID}
     , #{CTADR}
     , #{CSMG_PIC_FLNM}
     , #{CSMG_BGNG_YMD}
     , #{CSMG_END_YMD}
     , #{CSMG_DTL_DCD}
     , TO_DATE(#{FRST_REG_PTM},'YYYYMMDDHH24MISS')
     , TO_DATE(#{LAST_MDFCN_PTM},'YYYYMMDDHH24MISS')
     )

mapper.select:

/* isry.itgcm.linkmng.outsd.mapper.LinkMohwJobMapper.selectRcptInstNo(개인식별번호로  접수기관번호 구하기) */
SELECT RCPT_INST_NO   AS RCPT_INST_NO               
FROM SEA200 /* 대상자정보 */
WHERE 1=1
  AND INDV_IDNTFC_NO = #{INDV_IDNTFC_NO}


/* isry.itgcm.linkmng.outsd.mapper.LinkMohwJobMapper.selectUntTaskwkSecd(접수기관번호로  단위업무구분코드 구하기) */
SELECT UNT_TASKWK_SE_CD   AS UNT_TASKWK_SE_CD               
FROM SAA000 /* 통합기관 */
WHERE 1=1
  AND INST_NO = #{sRqstSrvInstId}
